    "correctAnswer": "Νεφρών",
    "explanation": "<p>Η πορφύρα Henoch-Schonlein είναι μια αυτοάνοση αγγειίτιδα, συχνότερη στα αγόρια. Τα συμπτώματα περιλαμβάνουν ψηλαφητή πορφύρα (δερματικό εξάνθημα), πόνο στις αρθρώσεις και γαστρεντερικά συμπτώματα όπως κοιλιακό άλγος και έμετο.</p>\n<p>Ενώ μπορεί να επηρεάσει διάφορα συστήματα οργάνων, η πιο σημαντική νοσηρότητα και θνησιμότητα οφείλεται στην προσβολή των νεφρών, η οποία εμφανίζεται σε έως και 50% των περιπτώσεων. Η προσβολή των νεφρών μπορεί να παρουσιαστεί ως αιματουρία,πρωτεϊνουρία και ακόμη και νεφρωσικό σύνδρομο.</p>"
