    "explanation": "<p>Η οξεία περικαρδίτιδα είναι μια φλεγμονώδης νόσος του περικαρδίου, του εξωτερικού καλύμματος της καρδιάς. Εκδηλώνεται συνήθως με πόνο στην προκάρδια χώρα και ήχο τριβής κατά την ακρόαση που οφείλεται στην τριβή των φλεγμονωδών ιστών του περικαρδίου. Επιπλέον, η οξεία περικαρδίτιδα μπορεί να συνοδεύεται από ηλεκτροκαρδιογραφικές αλλοιώσεις, όπως αύξηση του ST και χαμηλά QRS.</p>"
