    "correctAnswer": "Τα B, D (C) και D",
    "explanation": "<p>Τα αιμοπετάλια παράγονται στον μυελό των οστών από τα μητρικά κύτταρα που ονομάζονται Μεγακαρυοκύτταρα και είναι κατ’ ουσίαν κυτταρικά θραύσματα δηλαδή είναι απύρηνα κύτταρα.</p>\n<p>Οι φυσιολογικές τιμές των αιμοπεταλίων είναι 150.000/mL – 450.000/μ L. Η αύξηση των τιμών καλείται θρομβοκυττάρωση και η ελάττωση θρομβοπενία.</p>\n<p>Η Θρομβοκυττάρωση μπορεί να είναι είτε αντιδραστικού τύπου / Δευτεροπαθής, είτε αυτόνομη (Νεοπλασματικού τύπου) / Πρωτοπαθής.</p>\n<p>Ποια είναι τα αίτια της αντιδραστικής Δευτεροπαθούς θρομβοκυττάρωσης;</p>\n<p>1. Αναιμία: Απώλεια αίματος, Σιδηροπενία, αιμόλυση, θεραπεία με βιταμίνη Β12. 2. Λοιμώξεις: Ιογενείς, μικροβιακές, μυκοβακτηρίδια, μηκητιάσεις. 3. Φλεγμονές: μη-λοιμώδεις, Ρευματολογικές, τραύμα, κακοήθειες, εγκαύματα, ιστική βλάβη, έμφραγμα, μετεγχειρητικά παγκρεατίτις, φλεγμονώδης νόσος του εντέρου, έντονη άσκηση. 4. Μετά από Σπληνεκτομή.</p>"
