    "correctAnswer": "Όλα τα ανωτέρω",
    "explanation": "<p>Α) Η ευαισθητοποίηση της πρωτότοκου μπορεί να συμβεί μετά από αποβολή ή προκαλούμενη άμβλωση: Οι γυναίκες με αρνητικά Rh μπορεί να ευαισθητοποιηθούν σε Rh-θετικά αιμοσφαίρια εάν εκτεθούν σε αυτά κατά τη διάρκεια αποβολής, προκαλούμενης αποβολής ή άλλων συμβάντων που προκαλούν ανάμειξη αίματος μητέρας και εμβρύου.</p>\n<p>Β) Μπορεί να προκαλέσει εμβρυϊκό ύδρωπα: Ο εμβρυϊκός υδρωπας μπορεί να προκληθεί από σοβαρή εμβρυϊκή αναιμία που προκαλείται από ασυμβατότητα Rh, καθώς το έμβρυο αναπτύσσει συσσώρευση υγρού στους ιστούς και τα όργανά του.</p>\n<p>Γ) Ο μητρικός εμβολιασμός κατά της D εντός 72 ωρών μετά τον τοκετό μείωσε τη συχνότητα της νόσου: Η χορήγηση Rh ανοσοσφαιρίνης (RhIg) σε μητέρες με αρνητικά Rh εντός 72 ωρών μετά τον τοκετό, ένα θετικο Rh μωρο μπορεί να αποτρέψει την ευαισθητοποίηση της μητέρας. μειώνοντας έτσι τον κίνδυνο ασυμβατότητας Rh σε μελλοντικές εγκυμοσύνες.</p>\n<p>Δ) Η εμβρυϊκή αναιμία μπορεί να είναι συνέπεια της νόσου και να απαιτεί ενδομήτρια μετάγγιση: Σε σοβαρές περιπτώσεις ασυμβατότητας Rh, η εμβρυϊκή αναιμία μπορεί να εμφανιστεί ως αποτέλεσμα των αντισωμάτων της μητέρας να καταστρέφουν τα ερυθρά αιμοσφαίρια του εμβρύου. Σε τέτοιες περιπτώσεις, η ενδομήτρια μετάγγιση αίματος μπορεί να είναι απαραίτητη για τη θεραπεία της αναιμίας και τη βελτίωση των πιθανοτήτων επιβίωσης του εμβρύου.</p>"
