    "explanation": "<p>Σχόλιο: Ο σύνδρομος Eisenmenger είναι μια σπάνια αλλά σοβαρή επιπλοκή της καρδιακής πάθησης όπου η αντίστροφη ροή του αίματος στην καρδιά προκαλεί αύξηση της πίεσης στα πνευμονικά αγγεία. Αυτό οφείλεται σε μια εκτεταμένη επικοινωνία μεταξύ του συστήματος κυκλοφορίας του αίματος στην κοιλία της καρδιάς και του πνευμονικού κυκλώματος.</p>"
